import{_ as t,o as r,c as a,a0 as i}from"./chunks/framework.DScjKhBS.js";const h=JSON.parse('{"title":"Reports","description":"Research and insight reports from Elixirr Digital.","frontmatter":{"layout":"doc","title":"Reports","description":"Research and insight reports from Elixirr Digital."},"headers":[],"relativePath":"reports/index.md","filePath":"reports/index.md"}'),o={name:"reports/index.md"};function n(s,e,d,l,p,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h1><p>Research and insight reports — same Elixirr Digital branding and site structure. Each report is self-contained with its own sections and sidebar.</p><h2 id="key-takeaways" tabindex="-1">Key takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key takeaways&quot;">​</a></h2><ul><li>AI-assisted development works best when human merge accountability remains explicit.</li><li>PR review quality is a throughput and cognitive-load problem, not just a tooling problem.</li><li>Governance controls (data handling, security checks, auditability) need to be designed into delivery workflows, not bolted on.</li><li>Smaller, intent-rich PRs consistently improve review speed, depth, and reliability.</li><li>Most reports include operational templates and phased rollout plans, not only theory.</li></ul><h2 id="available-reports" tabindex="-1">Available reports <a class="header-anchor" href="#available-reports" aria-label="Permalink to &quot;Available reports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Report</th><th>Description</th></tr></thead><tbody><tr><td><a href="./reports/dark-factory/">Dark Factories &amp; AI-Generated Code</a></td><td>Spec-driven development, consultancy dynamics, and adoption for PHP, WordPress and Laravel teams.</td></tr><tr><td><a href="./reports/theme-only-audit/">Theme-only theme audit</a></td><td>Current nine-part theme-only audit, including WordPress 7.0 and <code>autoRegister</code> context, migration, and roadmap.</td></tr><tr><td><a href="./reports/theme-only-audit-2/">Theme-only theme audit (2)</a></td><td>Historic prior edition, frozen snapshot for reference (before the WordPress 7.0 update).</td></tr><tr><td><a href="./reports/ai-wp-laravel-pipeline/">AI in the WordPress + Laravel Pipeline</a></td><td>Structural AI integration beyond code completion: PR review, refactoring, migration, testing, documentation, tooling, security, 90-day pilot, KPIs, and risks.</td></tr><tr><td><a href="./reports/ai-augmented-dev-pipeline/">AI-Augmented Development Pipelines (Reconciled)</a></td><td>Reconciled plan: CI + Bionic + Cursor at £200 pilot; guardrails, governance, 90-day roadmap, KPIs, and risk register.</td></tr><tr><td><a href="./reports/ai-transformation-programme/">AI Transformation Research Programme</a></td><td>Strategic AI transition programme: workstreams, prioritisation matrix, 12-month roadmap, PoC templates, governance and policy, capability maturity model.</td></tr><tr><td><a href="./reports/agentic-engineering-techniques/">Agentic Engineering Techniques</a></td><td>Research analysis of the Agentic Engineering Book — technique inventory, gap analysis, pattern matching, and prioritised action plan for the multi-agent research workflow.</td></tr><tr><td><a href="./reports/ai-as-an-interface/">AI as an Interface Layer</a></td><td>Hows My Commute case study: production AI integration, OpenAPI + OAuth as a reusable pattern, security and strategic implications.</td></tr><tr><td><a href="./reports/ai-second-brain/">AI Second Brain</a></td><td>How AI can create and consume a shared second brain: data lifecycle, meeting notes, coding agents, prompt management, tool comparison, governance, 90-day pilot, KPIs, and risks.</td></tr><tr><td><a href="./reports/structured-prompt-driven/">Structured-Prompt-Driven Development (SPDD)</a></td><td>Research microsite on Thoughtworks&#39; SPDD method (Fowler, 2026): REASONS Canvas, openspdd workflow, billing case study, skills and fitness — links to the primary article.</td></tr><tr><td><a href="./reports/agentic-framework-comparison/">nWave vs Superpowers</a></td><td>Comparative technical research on two agentic development approaches, plus a <a href="./reports/agentic-framework-comparison/00-executive-summary.html">one-page leadership brief and decision matrix</a>.</td></tr><tr><td><a href="./reports/pr-review-continuity/">PR Review Continuity Under Capacity Loss</a></td><td>Operational model for periods when reviewers cannot fully understand or deeply review every PR: sizing rules, risk tiers, AI guardrails, and a 30-60-90 rollout.</td></tr><tr><td><a href="./reports/agency-project-lifecycle/">Agency Project Lifecycle — AI Opportunity Analysis</a></td><td>Full-lifecycle analysis from estimation to post-launch: standard workflow, pain points, AI opportunity map, and prioritised recommendations.</td></tr><tr><td><a href="./reports/edi-repos-analysis/">EDI Repository Portfolio Analysis</a></td><td>Senior-engineer review of 57 Elixirr/iOLAP repos — AI enablement, academy, DSO, MSDP, client delivery, and WordPress transfer guidance.</td></tr></tbody></table><p>More reports will be added here. Each has its own table of contents and navigation in the sidebar.</p><hr><p><em>Part of Elixirr Digital — Your digital partner.</em></p>',9)])])}const u=t(o,[["render",n]]);export{h as __pageData,u as default};
